//! What a SpecFluxFrame inherits from CmpFrame, checked against the C
//! library.
//!
//! `specflux_primary_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/specflux_primary_probe.c`. A SpecFluxFrame's
//! System is "Compound" (cmpframe.c `GetSystem`), and `PrimaryFrame`
//! descends into its SpecFrame and FluxFrame, so a SpecFrame template finds
//! the spectral axis of a SpecFluxFrame, alone or inside a CmpFrame
//! (cmpframe.c `PrimaryFrame`).

#[path = "specflux_primary_oracle/cases.rs"]
mod cases;

use ast_core::coords::PointSet;
use ast_core::frames::{
    BasicFrameBuilder, CmpFrame, FluxFrame, FluxSystem, Frame, FrameRef, SpecFluxFrame, SpecFrame,
    SpecSystem,
};

fn specflux() -> SpecFluxFrame {
    let mut sp = SpecFrame::new(SpecSystem::Freq);
    sp.set_unit(1, "GHz").unwrap();
    SpecFluxFrame::new(sp, flux(None))
}

fn flux(template: Option<(usize, &str)>) -> FluxFrame {
    let mut f = FluxFrame::with_spec_val(1.4e9, None);
    f.set_system(FluxSystem::FluxDen).unwrap();
    if let Some((max_axes, unit)) = template {
        f.set_max_axes(max_axes).unwrap();
        f.set_unit(1, unit).unwrap();
    }
    f
}

fn spec_template(max_axes: usize) -> SpecFrame {
    let mut t = SpecFrame::new(SpecSystem::Wavelen);
    t.set_unit(1, "nm").unwrap();
    t.set_max_axes(max_axes).unwrap();
    t
}

fn found(target: &dyn Frame, template: &dyn Frame) -> Option<f64> {
    let fs = target.find_frame_template(template, "").unwrap()?;
    let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
    let cols: Vec<[f64; 1]> = cases::POINT[..target.naxes()]
        .iter()
        .map(|&v| [v])
        .collect();
    let cols: Vec<&[f64]> = cols.iter().map(|c| &c[..]).collect();
    let out = map
        .transform(&PointSet::from_columns(&cols).unwrap(), true)
        .unwrap();
    Some(out.point(0)[0])
}

#[test]
fn system_is_compound_as_in_the_c_library() {
    assert_eq!(specflux().system_string().unwrap(), Some(cases::SYSTEM));
}

#[test]
fn templates_find_component_axes_as_in_the_c_library() {
    let sff = specflux();
    let cmp = CmpFrame::new(
        Box::new(specflux()),
        Box::new(BasicFrameBuilder::new(1).build().unwrap()),
    );
    let mut failures = Vec::new();
    for &(name, want) in cases::CASES {
        let got = match name {
            "spec_in_specflux" => found(&sff, &spec_template(2)),
            "spec_in_cmp" => found(&cmp, &spec_template(3)),
            "flux_in_specflux" => found(&sff, &flux(Some((2, "mJy")))),
            "flux_in_cmp" => found(&cmp, &flux(Some((3, "mJy")))),
            other => panic!("no Rust set-up for case {other}"),
        };
        if got != want {
            failures.push(format!("{name}: got {got:?}, C gives {want:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
